const q = $input.first().json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.WEBHOOK_VERIFY_TOKEN;
return [{ json: { body: ok ? q['hub.challenge'] : 'token invalido', statusCode: ok ? 200 : 403 } }];

const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  for (const e of (body.entry || [])) {
    for (const ch of (e.changes || [])) {
      const v = ch.value || {};
      const contacto = (v.contacts && v.contacts[0]) || {};
      for (const m of (v.messages || [])) {
        let texto = '';
        let inter_id = '';
        let imagen_id = '';
        if (m.type === 'text') texto = (m.text && m.text.body) || '';
        else if (m.type === 'image') imagen_id = (m.image && m.image.id) || '';
        else if (m.type === 'interactive') {
          const it = m.interactive || {};
          if (it.type === 'list_reply') inter_id = (it.list_reply && it.list_reply.id) || '';
          else if (it.type === 'button_reply') inter_id = (it.button_reply && it.button_reply.id) || '';
        }
        out.push({ json: {
          wa_id: m.from,
          nombre: (contacto.profile && contacto.profile.name) || '',
          tipo: m.type,
          texto,
          inter_id,
          imagen_id,
          message_id: m.id
        }});
      }
    }
  }
}
return out;

// ============ CEREBRO DEL BOT (sesiones + pedidos + Gemini) ============
const H = this.helpers;
const crypto = require('crypto');

const CAT_LABEL = { deportivas: 'Deportivas', casuales: 'Casuales', urbanas: 'Urbanas' };
const CAT_ORDER = ['deportivas', 'casuales', 'urbanas'];
const FS_BASE = 'https://firestore.googleapis.com/v1/projects/varman-crew/databases/(default)/documents';

// ---------- utilidades ----------
function fmtPrecio(n) {
  return '$' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}
function unwrap(v) {
  if (v == null) return null;
  if ('integerValue' in v) return parseInt(v.integerValue, 10);
  if ('doubleValue' in v) return v.doubleValue;
  if ('booleanValue' in v) return v.booleanValue;
  if ('stringValue' in v) return v.stringValue;
  if ('arrayValue' in v) return (v.arrayValue.values || []).map(unwrap);
  return null;
}
function parseCatalogo(fsJson) {
  const docs = (fsJson.documents || []);
  const items = docs.map((d) => {
    const f = d.fields || {}; const o = {};
    for (const k in f) o[k] = unwrap(f[k]);
    return o;
  }).filter((o) => o.activo !== false);
  items.sort((a, b) => (a.orden || 999) - (b.orden || 999));
  return items;
}
function toFs(obj) {
  const fields = {};
  for (const k in obj) {
    const v = obj[k];
    if (v === undefined || v === null) continue;
    if (typeof v === 'number') fields[k] = { integerValue: String(Math.round(v)) };
    else if (typeof v === 'boolean') fields[k] = { booleanValue: v };
    else fields[k] = { stringValue: String(v) };
  }
  return fields;
}
function fromFs(doc) {
  if (!doc || !doc.fields) return null;
  const o = {};
  for (const k in doc.fields) o[k] = unwrap(doc.fields[k]);
  return o;
}

// ---------- acceso admin a Firestore (service account) ----------
function b64url(buf) {
  return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
async function tokenAdmin() {
  const sa = JSON.parse(Buffer.from($env.FIREBASE_SA_B64, 'base64').toString('utf8'));
  const now = Math.floor(Date.now() / 1000);
  const header = b64url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const claims = b64url(JSON.stringify({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/datastore',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now, exp: now + 3600
  }));
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(header + '.' + claims);
  const jwt = header + '.' + claims + '.' + b64url(signer.sign(sa.private_key));
  const r = await H.httpRequest({
    method: 'POST', url: 'https://oauth2.googleapis.com/token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + jwt,
    timeout: 15000, json: true
  });
  return r.access_token;
}
async function fsGet(tok, path) {
  try {
    const d = await H.httpRequest({ method: 'GET', url: FS_BASE + '/' + path,
      headers: { Authorization: 'Bearer ' + tok }, json: true, timeout: 15000 });
    return fromFs(d);
  } catch (e) { return null; }
}
async function fsSet(tok, path, obj) {
  await H.httpRequest({ method: 'PATCH', url: FS_BASE + '/' + path,
    headers: { Authorization: 'Bearer ' + tok, 'Content-Type': 'application/json' },
    body: { fields: toFs(obj) }, json: true, timeout: 15000 });
}
async function fsDel(tok, path) {
  try {
    await H.httpRequest({ method: 'DELETE', url: FS_BASE + '/' + path,
      headers: { Authorization: 'Bearer ' + tok }, json: true, timeout: 15000 });
  } catch (e) {}
}
async function fsAdd(tok, colPath, obj) {
  const d = await H.httpRequest({ method: 'POST', url: FS_BASE + '/' + colPath,
    headers: { Authorization: 'Bearer ' + tok, 'Content-Type': 'application/json' },
    body: { fields: toFs(obj) }, json: true, timeout: 15000 });
  return d.name.split('/documents/')[1];
}

// ---------- constructores de mensajes WhatsApp ----------
function msjTexto(to, body) {
  return { messaging_product: 'whatsapp', to, type: 'text', text: { body } };
}
function listaCategorias(to, catalogo, bodyTexto) {
  const counts = {};
  for (const p of catalogo) counts[p.cat] = (counts[p.cat] || 0) + 1;
  const rows = CAT_ORDER.filter((c) => counts[c]).map((c) => ({
    id: 'cat:' + c, title: CAT_LABEL[c], description: counts[c] + ' modelos disponibles'
  }));
  return { messaging_product: 'whatsapp', to, type: 'interactive', interactive: {
    type: 'list',
    header: { type: 'text', text: 'VarMan Crew 👟' },
    body: { text: (bodyTexto || '¡Hola! Bienvenido a *VarMan Crew*. Estos son nuestros estilos. ¿Cuál quieres ver?').slice(0, 1024) },
    footer: { text: 'Toca «Ver categorías»' },
    action: { button: 'Ver categorías', sections: [{ title: 'Categorías', rows }] }
  }};
}
function listaModelos(to, catalogo, cat) {
  const label = CAT_LABEL[cat] || cat;
  let modelos = catalogo.filter((p) => p.cat === cat);
  const total = modelos.length;
  const hayMas = total > 10;
  modelos = modelos.slice(0, 10);
  const rows = modelos.map((p) => {
    const desc = fmtPrecio(p.precio) + (p.tag ? '  ·  ' + p.tag : '');
    return { id: 'ref:' + p.ref, title: 'Referencia ' + p.ref, description: desc.slice(0, 72) };
  });
  const bodyTxt = hayMas
    ? 'Estos son algunos de nuestros modelos ' + label.toLowerCase() + ' (los primeros 10 de ' + total + '). Toca el que te guste 👇'
    : 'Nuestros modelos ' + label.toLowerCase() + '. Toca el que te guste 👇';
  return { messaging_product: 'whatsapp', to, type: 'interactive', interactive: {
    type: 'list',
    header: { type: 'text', text: 'VarMan Crew · ' + label },
    body: { text: bodyTxt },
    footer: { text: 'Envíos a todo el país' },
    action: { button: 'Ver modelos', sections: [{ title: label, rows }] }
  }};
}
function botonesPago(to, total) {
  return { messaging_product: 'whatsapp', to, type: 'interactive', interactive: {
    type: 'button',
    body: { text: '¡Perfecto! 📦 Tu pedido va quedando listo.\n\nTotal a pagar: *' + fmtPrecio(total) + '*\n\n¿Cómo prefieres pagar?' },
    action: { buttons: [
      { type: 'reply', reply: { id: 'pay:nequi', title: 'Nequi' } },
      { type: 'reply', reply: { id: 'pay:daviplata', title: 'Daviplata' } },
      { type: 'reply', reply: { id: 'pay:breb', title: 'Bre-B' } }
    ]}
  }};
}
const PAGOS = {
  nequi: { nombre: 'Nequi', dato: () => $env.PAGO_NEQUI },
  daviplata: { nombre: 'Daviplata', dato: () => $env.PAGO_DAVIPLATA },
  breb: { nombre: 'Bre-B', dato: () => $env.PAGO_BREB }
};

// ---------- flujo principal ----------
const parsed = $('Parsear mensaje').item.json;
const catalogo = parseCatalogo($json);
const to = parsed.wa_id;
const sel = (parsed.inter_id || '').trim();
const texto = (parsed.texto || '').trim();
const dueno = String($env.OWNER_WHATSAPP || '').replace(/\D/g, '');
const mensajes = [];

const tok = await tokenAdmin();
const SES_PATH = 'tiendas/varman/botSesiones/' + to;
let ses = await fsGet(tok, SES_PATH);
// sesion vieja (>24h) = sesion muerta
if (ses && ses.updatedAt && (Date.now() - Date.parse(ses.updatedAt)) > 24 * 3600 * 1000) {
  await fsDel(tok, SES_PATH);
  ses = null;
}
async function guardarSes(obj) {
  await fsSet(tok, SES_PATH, Object.assign({}, obj, { updatedAt: new Date().toISOString() }));
}

if (/^(cancelar|cancela|cancel)$/i.test(texto) && ses) {
  await fsDel(tok, SES_PATH);
  mensajes.push(msjTexto(to, 'Listo, cancelé el pedido 👍. Cuando quieras retomar, escribe *hola* y te muestro el catálogo.'));

} else if (sel.startsWith('cat:')) {
  if (ses) await fsDel(tok, SES_PATH); // volvio a navegar
  mensajes.push(listaModelos(to, catalogo, sel.slice(4)));

} else if (sel.startsWith('ref:')) {
  const ref = sel.slice(4);
  const p = catalogo.find((x) => x.ref === ref);
  if (p) {
    await guardarSes({ estado: 'talla', ref, precio: p.precio, nombrePerfil: parsed.nombre || '' });
    mensajes.push(msjTexto(to, '¡Buena elección! 🔥\n\nLa *Referencia ' + ref + '* cuesta *' + fmtPrecio(p.precio) + '*.\n\n¿Qué talla buscas? Escríbeme el número (tenemos de la 36 a la 45). Si quieres empezar de nuevo, escribe *cancelar*.'));
  } else {
    mensajes.push(msjTexto(to, 'No encontré esa referencia 😅. Escribe *hola* para ver el catálogo de nuevo.'));
  }

} else if (sel.startsWith('pay:') && ses && (ses.estado === 'pago' || ses.estado === 'comprobante')) {
  const clave = sel.slice(4);
  const met = PAGOS[clave];
  if (met) {
    await guardarSes(Object.assign({}, ses, { estado: 'comprobante', metodo: met.nombre }));
    mensajes.push(msjTexto(to, 'Pagas por *' + met.nombre + '* a este número/llave:\n\n👉 ' + met.dato() + '\n\nTotal: *' + fmtPrecio(ses.precio) + '*\n\nCuando hagas el pago, mándame la *foto del comprobante* aquí mismo 📸 y dejamos tu pedido confirmado.'));
  }

} else if (ses && ses.estado === 'talla') {
  const m = texto.match(/\b(3[6-9]|4[0-5])\b/);
  if (m) {
    await guardarSes(Object.assign({}, ses, { estado: 'datos', talla: m[1] }));
    mensajes.push(msjTexto(to, '¡Talla ' + m[1] + ' anotada! ✅\n\nAhora regálame en un solo mensaje los datos de envío:\n\n*Nombre completo*\n*Dirección*\n*Ciudad*\n*Teléfono de contacto*'));
  } else {
    mensajes.push(msjTexto(to, 'Manejamos tallas de la *36 a la 45* 👟. Escríbeme solo el número (ej: *40*), o *cancelar* para empezar de nuevo.'));
  }

} else if (ses && ses.estado === 'datos') {
  if (texto.length >= 15) {
    await guardarSes(Object.assign({}, ses, { estado: 'pago', datosEnvio: texto.slice(0, 500) }));
    mensajes.push(botonesPago(to, ses.precio));
  } else {
    mensajes.push(msjTexto(to, 'Creo que faltan datos 🙈. Mándame en un solo mensaje: *nombre completo, dirección, ciudad y teléfono*.'));
  }

} else if (ses && ses.estado === 'pago') {
  // escribio texto en vez de tocar el boton
  const m = texto.match(/nequi|daviplata|bre/i);
  if (m) {
    const clave = m[0].toLowerCase().startsWith('bre') ? 'breb' : m[0].toLowerCase();
    const met = PAGOS[clave];
    await guardarSes(Object.assign({}, ses, { estado: 'comprobante', metodo: met.nombre }));
    mensajes.push(msjTexto(to, 'Pagas por *' + met.nombre + '* a este número/llave:\n\n👉 ' + met.dato() + '\n\nTotal: *' + fmtPrecio(ses.precio) + '*\n\nCuando hagas el pago, mándame la *foto del comprobante* aquí mismo 📸.'));
  } else {
    mensajes.push(botonesPago(to, ses.precio));
  }

} else if (ses && ses.estado === 'comprobante') {
  if (parsed.imagen_id) {
    const pedido = {
      cliente_nombre: ses.nombrePerfil || parsed.nombre || '',
      cliente_wa: to,
      datos_envio: ses.datosEnvio || '',
      ref: ses.ref,
      talla: ses.talla || '',
      cantidad: 1,
      total: ses.precio,
      metodo_pago: ses.metodo || '',
      comprobante_media_id: parsed.imagen_id,
      estado: 'pagado (por verificar)',
      canal: 'whatsapp-bot',
      creado: new Date().toISOString()
    };
    const pedidoPath = await fsAdd(tok, 'tiendas/varman/pedidos', pedido);
    await fsDel(tok, SES_PATH);
    mensajes.push(msjTexto(to, '¡Pedido recibido! 🎉\n\n*Referencia ' + ses.ref + '* · Talla ' + ses.talla + ' · ' + fmtPrecio(ses.precio) + '\n\nVamos a verificar tu pago y te confirmamos el envío por aquí mismo. ¡Gracias por comprar en VarMan Crew! 👟'));
    if (dueno && dueno !== to) {
      mensajes.push(msjTexto(dueno, '🛒 *NUEVO PEDIDO (por verificar)*\n\nRef: ' + ses.ref + ' · Talla ' + ses.talla + '\nTotal: ' + fmtPrecio(ses.precio) + ' por ' + (ses.metodo || '?') + '\nCliente: ' + (ses.nombrePerfil || '(sin nombre)') + ' · +' + to + '\nEnvío: ' + (ses.datosEnvio || '') + '\n\n📎 Comprobante recibido (en el chat del cliente).\nPedido guardado: ' + pedidoPath));
    }
  } else {
    mensajes.push(msjTexto(to, 'Cuando puedas, mándame la *foto del comprobante* 📸 para confirmar tu pedido. Si quieres cambiar algo, escribe *cancelar*.'));
  }

} else {
  // ---------- sin sesion: texto libre -> Gemini ----------
  const SISTEMA = 'Eres el clasificador de intenciones del bot de WhatsApp de VarMan Crew, una tienda colombiana de zapatos (tenis/sneakers). Analiza el mensaje del cliente y responde SOLO un JSON valido (sin markdown) con esta forma: {"intent":"<una de: saludo|ver_catalogo|pregunta_precio|comprar|hablar_humano|otro>","respuesta":"<respuesta corta y calida en español colombiano, tono vendedor amable, max 2 frases, puede usar 1 emoji>"} Reglas: "saludo": saludos o inicios de conversacion, la respuesta da la bienvenida a VarMan Crew. "ver_catalogo": pide ver zapatos, modelos, catalogo, fotos, o pregunta por un modelo o marca. "pregunta_precio": pregunta precios en general o de una categoria. "comprar": ya quiere comprar o pedir algo concreto. "hablar_humano": pide hablar con una persona, asesor o el dueño. "otro": nada de lo anterior (quejas, envios, etc.), da una respuesta util y ofrece ver el catalogo o hablar con un asesor. Contexto: precios entre $235.000 y $480.000 COP, envios a todo Colombia, pagos por Nequi/Daviplata/Bre-B.';
  let intent = 'saludo';
  let respuesta = '';
  if (texto) {
    try {
      const r = await H.httpRequest({
        method: 'POST',
        url: 'https://generativelanguage.googleapis.com/v1beta/models/' + ($env.GEMINI_MODEL || 'gemini-2.5-flash-lite') + ':generateContent',
        headers: { 'Content-Type': 'application/json', 'x-goog-api-key': $env.GEMINI_API_KEY },
        body: {
          system_instruction: { parts: [{ text: SISTEMA }] },
          contents: [{ role: 'user', parts: [{ text: texto.slice(0, 500) }] }],
          generationConfig: { temperature: 0.3, maxOutputTokens: 200, responseMimeType: 'application/json' }
        },
        json: true, timeout: 15000
      });
      const out = JSON.parse(r.candidates[0].content.parts[0].text);
      if (out && out.intent) { intent = out.intent; respuesta = out.respuesta || ''; }
    } catch (e) { intent = 'saludo'; respuesta = ''; }
  }
  if (intent === 'hablar_humano') {
    mensajes.push(msjTexto(to, respuesta || '¡Claro! Ya le avisé a nuestro equipo 😊. En un momento te escriben desde el +57 320 225 0619.'));
    if (dueno && dueno !== to) {
      mensajes.push(msjTexto(dueno, '🔔 *Cliente pide atención humana*\n\nNombre: ' + (parsed.nombre || '(sin nombre)') + '\nWhatsApp: +' + to + '\nÚltimo mensaje: "' + texto + '"'));
    }
  } else if (intent === 'otro') {
    mensajes.push(msjTexto(to, respuesta || 'Con gusto te ayudamos 😊. ¿Quieres ver el catálogo? Escribe *hola* o dime qué necesitas.'));
  } else if (intent === 'comprar') {
    if (respuesta) mensajes.push(msjTexto(to, respuesta));
    mensajes.push(listaCategorias(to, catalogo, 'Mira nuestro catálogo y toca el modelo que buscas 👇'));
  } else {
    mensajes.push(listaCategorias(to, catalogo, respuesta || undefined));
  }
}

return mensajes.map((m) => ({ json: m }));
